#define Res vec2(iResolution.xy)
#define Res0 vec2(textureSize(iChannel0,0))
#define Res1 vec2(textureSize(iChannel1,0))
#define PI  3.14159265359
#define PI2 6.28318530718
#define PIH 1.57079632679
#define SQH sqrt(.5)

#define PIH 1.57079632679

#define ROTM(ang) mat2(cos(ang-vec2(0,PIH)),-sin(ang-vec2(0,PIH)))

vec3 rotZ(float ang, vec3 p) { return vec3(ROTM(ang)*p.xy,p.z); }
vec3 rotX(float ang, vec3 p) { return rotZ(ang,p.yzx).zxy; }

float fermi(float x) {
    return 1./(1.+exp(-x));
}

float smin0(float a, float b, float k)
{
    return mix(a,b,fermi((a-b)/k))-k*exp(-(abs(a)+abs(b))/k/2.);
}

float smin(float a, float b, float k) { return smin0(a,b,k); }

float smax(float a, float b, float k) { return -smin(-a,-b,k); }

vec4 getRand(int i) { return texelFetch(iChannel1,ivec2(i,i%256)%256,0); }

//float length2(vec2 v) { vec2 q=abs(v); return max(q.x,q.y); }
float length2(vec2 v) { vec2 q=abs(v); return q.x*.8+q.y*1.2; }

bool g_bump=false;

float dist(vec3 p)
{
    float ScrewR=.5;
    float WindH=ScrewR*.45;
    float NutH=.5;
    float NutW=2.;

    float dn=1000.,ds,d2,d=10000.;
    float dz=iTime*.1;
    float dzs=sin(iTime)*.2;

    float screwAng=((dz+dzs)/WindH)*PI2;

    // screw
    vec3 p0=p;
    p.z-=dz;
    //if (g_bump) p+=textureLod(iChannel1,p.xy*.7,0.).xyz*.00025;
    //shane deamnded some anisotrppy ;-)
    if (g_bump) p+=textureLod(iChannel1,p.xy*dot(p.xy,p.xy)*dot(p.xy,p.xy)*1.7-p.z*.1,0.).xyz*.0007;
    d2=length(p.xy)-ScrewR;
    d=min(d,d2);
    float ang=atan(p.y,p.x);
    d2=length2(vec2(length(p.xy)-ScrewR,(fract(p.z/WindH+ang/PI2)-.5)*WindH))-WindH*.5;
    d=smax(d,-d2,.006);
    ds=d;

    //nut
    p=p0;
    p.xy*=ROTM(screwAng); ang-=screwAng;
    p.z+=dzs;
    if (g_bump) p+=textureLod(iChannel1,p.xy*.17,0.).xyz*.0005;
    //outer cone
    d2=dot(vec2(length(p.xy),abs(p.z)),normalize(vec2(1,1)))-1.03;
    dn=min(dn,d2);
    dn=smax(dn,(abs(p.z)-NutH),.01);
    dn=smax(dn,-(ds-.02),.01);
    float angN=floor(ang/PI2*6.+.5)*PI2/6.;
    dn=smax(dn,dot(p.xy,cos(angN-vec2(0,PIH)))-NutW*.5,.005);
    //inner cone
    d2=dot(vec2(length(p.xy),abs(p.z)),normalize(vec2(-1,1.1)))-.0;
    dn=smax(dn,d2,.005);
    //dn=max(dn,-max(-p0.x,p0.y));
    d=min(d,dn);

    return d;
}

vec3 getGrad(vec3 p, float eps) 
{ 
    vec2 d=vec2(eps,0); 
    float d0=dist(p);
    return vec3(dist(p+d.xyy)-d0,dist(p+d.yxy)-d0,dist(p+d.yyx)-d0)/eps; 
}

void march(inout vec3 pos, vec3 dir)
{
    float eps=.001;
    for(int i=0;i<180;i++)
    {
        float d=dist(pos);
        pos+=dir*d*.7;
        if (d<eps) break;
    }
}

void getTrafo(inout vec3 pos, inout vec3 dir, vec2 fc)
{
    vec2 sc=(fc-Res*.5)/Res.x*2.;
    dir=normalize(vec3(0,0,-2.5)+vec3(sc,0));
    pos=vec3(0,0,10./**exp(-iMouseData.z/3000.)*/);
    float ph = iMouse.x/Res.x*10.+2.;
    float th = iMouse.y/Res.y*10.+1.2;
    pos.yz=ROTM(th)*pos.yz;
    dir.yz=ROTM(th)*dir.yz;
    pos.xy=ROTM(ph)*pos.xy;
    dir.xy=ROTM(ph)*dir.xy;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 pos,dir;
    getTrafo(pos,dir,fragCoord);
    march(pos,dir);
    g_bump=true;
    vec3 n=normalize(getGrad(pos,.001)+.00001);
    fragColor.xyz=n*.05+.95;
    float diff=max(0.,dot(n,normalize(vec3(1,1,1))))*.5+.5;
    float ao=1.; for(float sc=1.;sc>.02;sc*=.5) ao*=.9+.1*dist(pos+n*sc)/sc;
    fragColor.xyz*=ao*diff;
    fragColor.xyz*=.4+.6*textureLod(iChannel0,reflect(dir,n),4.5).xyz;
    fragColor.w=1.;
}
